def transform(grid):
    """Encode each non-background object as one cell, grouping color 3 then 2."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            objects.append(color)
    order = {3: 0, 2: 1}
    objects.sort(key=lambda color: (order.get(color, 2), color))
    cells = objects[:6] + [0] * max(0, 6-len(objects))
    return [cells[:3], cells[3:6]]
